sp_widget.client_script:
api.controller = function($scope, $http) {

    var c = this;


    /* ==========================================
       USER ID
       ========================================== */

    var userId = '';


    try {

        var loginData =
            JSON.parse(
                localStorage.getItem('campusLogin')
            );


        if (loginData && loginData.user) {

            userId = loginData.user;

        }

    } catch (e) {

        console.log(
            'Unable to read campusLogin',
            e
        );

    }


    c.userId = userId;


    /* ==========================================
       DEFAULT SECTION
       ========================================== */

    c.activeSection = 'dashboard';


    /* ==========================================
       COMPLAINT
       ========================================== */

    c.complaint = {

        use_case: '',
        mess_hall: '',
        meal_type: '',
        problem_type: '',
        description: ''

    };


    c.file = null;

    c.complaintSuccess = false;

    c.complaintNumber = '';

    c.complaintSysId = '';

    c.submittingComplaint = false;

    c.formError = '';


    /* ==========================================
       FEEDBACK
       ========================================== */

    c.showFeedbackForm = false;

    c.selectedFeedbackSysId = '';

    c.submittingFeedback = false;

    c.feedbackError = '';


    c.feedbackForm = {

        number: '',
        base_problem: '',
        meal_type: '',
        problem_type: '',
        use_case: '',
        student: '',
        mess_hall: '',
        overall_rating: '',
        resolution_satisfaction: '',
        feedback_comments: ''

    };


    /* ==========================================
       SECTION CHANGE
       ========================================== */

    c.selectSection = function(section) {

        c.activeSection = section;


        /* Close feedback form when leaving feedback */

        if (section != 'feedback') {

            c.closeFeedback();

        }

    };


    /* ==========================================
       FILE SELECTED
       ========================================== */

    c.fileSelected = function(input) {

        if (
            input &&
            input.files &&
            input.files.length > 0
        ) {

            c.file = input.files[0];

        } else {

            c.file = null;

        }

    };


    /* ==========================================
       SUBMIT COMPLAINT
       ========================================== */

    c.submitComplaint = function() {

        c.formError = '';


        if (!c.userId) {

            c.formError =
                'Unable to identify the logged-in student.';

            return;

        }


        if (
            !c.complaint.use_case ||
            !c.complaint.mess_hall ||
            !c.complaint.meal_type ||
            !c.complaint.problem_type ||
            !c.complaint.description
        ) {

            c.formError =
                'Please fill all required fields.';

            return;

        }


        c.submittingComplaint = true;


        c.server.get({

            action: 'createComplaint',

            userId: c.userId,

            use_case:
                c.complaint.use_case,

            mess_hall:
                c.complaint.mess_hall,

            meal_type:
                c.complaint.meal_type,

            problem_type:
                c.complaint.problem_type,

            description:
                c.complaint.description

        }).then(function(response) {


            c.submittingComplaint = false;


            if (
                response.data &&
                response.data.complaintSuccess
            ) {


                c.complaintSuccess = true;


                c.complaintNumber =
                    response.data.complaintNumber;


                c.complaintSysId =
                    response.data.complaintSysId;


                /* ==========================================
                   ATTACHMENT
                   ========================================== */

                if (
                    c.file &&
                    c.complaintSysId
                ) {

                    var uploadUrl =
                        '/api/now/attachment/file' +
                        '?table_name=' +
                        'x_snc_campus_foo_1_food_complaint' +
                        '&table_sys_id=' +
                        encodeURIComponent(
                            c.complaintSysId
                        ) +
                        '&file_name=' +
                        encodeURIComponent(
                            c.file.name
                        );


                    $http({

                        method: 'POST',

                        url: uploadUrl,

                        data: c.file,

                        headers: {

                            'Content-Type':
                                undefined

                        }

                    });

                }


                /* Refresh dashboard data */

                c.server.update();


            } else {

                c.formError =
                    response.data.formError ||
                    'Unable to create complaint.';

            }

        }, function() {

            c.submittingComplaint = false;

            c.formError =
                'An error occurred while submitting the complaint.';

        });

    };


    /* ==========================================
       RESET COMPLAINT
       ========================================== */

    c.resetComplaint = function() {

        c.complaint = {

            use_case: '',
            mess_hall: '',
            meal_type: '',
            problem_type: '',
            description: ''

        };


        c.file = null;

        c.formError = '';


        var fileInput =
            document.getElementById(
                'complaintAttachment'
            );


        if (fileInput) {

            fileInput.value = '';

        }

    };


    /* ==========================================
       NEW COMPLAINT
       ========================================== */

    c.newComplaint = function() {

        c.complaintSuccess = false;

        c.complaintNumber = '';

        c.complaintSysId = '';

        c.resetComplaint();

    };


    /* ==========================================
       OPEN FEEDBACK
       ========================================== */

    c.openFeedback = function(sysId) {

        c.feedbackError = '';


        var feedback = null;


        for (
            var i = 0;
            i < c.data.feedbacks.length;
            i++
        ) {

            if (
                c.data.feedbacks[i].sys_id
                ==
                sysId
            ) {

                feedback =
                    c.data.feedbacks[i];

                break;

            }

        }


        if (!feedback) {

            c.feedbackError =
                'Feedback record not found.';

            return;

        }


        c.selectedFeedbackSysId =
            sysId;


        c.feedbackForm = {

            number:
                feedback.number || '',

            base_problem:
                feedback.base_problem || '',

            meal_type:
                feedback.meal_type || '',

            problem_type:
                feedback.problem_type || '',

            use_case:
                feedback.use_case || '',

            student:
                feedback.student || '',

            mess_hall:
                feedback.mess_hall || '',

            overall_rating:
                feedback.overall_rating || '',

            resolution_satisfaction:
                feedback.resolution_satisfaction || '',

            feedback_comments:
                feedback.feedback_comments || ''

        };


        c.showFeedbackForm = true;

    };


    /* ==========================================
       SUBMIT FEEDBACK
       ========================================== */

    c.submitFeedback = function() {

        c.feedbackError = '';


        if (!c.selectedFeedbackSysId) {

            c.feedbackError =
                'Please select a feedback record.';

            return;

        }


        if (!c.feedbackForm.overall_rating) {

            c.feedbackError =
                'Please select Overall Rating.';

            return;

        }


        if (
            !c.feedbackForm.resolution_satisfaction
        ) {

            c.feedbackError =
                'Please select Resolution Satisfaction.';

            return;

        }


        if (!c.userId) {

            c.feedbackError =
                'Unable to identify the logged-in student.';

            return;

        }


        c.submittingFeedback = true;


        c.server.get({

            action: 'submitFeedback',

            userId: c.userId,

            feedbackSysId:
                c.selectedFeedbackSysId,

            overall_rating:
                c.feedbackForm.overall_rating,

            resolution_satisfaction:
                c.feedbackForm.resolution_satisfaction,

            feedback_comments:
                c.feedbackForm.feedback_comments

        }).then(function(response) {


            c.submittingFeedback = false;


            if (
                response.data &&
                response.data.feedbackSuccess
            ) {

                c.showFeedbackForm = false;

                c.selectedFeedbackSysId = '';

                c.feedbackForm = {

                    number: '',
                    base_problem: '',
                    meal_type: '',
                    problem_type: '',
                    use_case: '',
                    student: '',
                    mess_hall: '',
                    overall_rating: '',
                    resolution_satisfaction: '',
                    feedback_comments: ''

                };


                c.server.update();

            } else {

                c.feedbackError =
                    'Unable to submit feedback.';

            }

        }, function() {

            c.submittingFeedback = false;

            c.feedbackError =
                'An error occurred while submitting feedback.';

        });

    };


    /* ==========================================
       CLOSE FEEDBACK
       ========================================== */

    c.closeFeedback = function() {

        c.showFeedbackForm = false;

        c.selectedFeedbackSysId = '';

        c.feedbackError = '';


        c.feedbackForm = {

            number: '',
            base_problem: '',
            meal_type: '',
            problem_type: '',
            use_case: '',
            student: '',
            mess_hall: '',
            overall_rating: '',
            resolution_satisfaction: '',
            feedback_comments: ''

        };

    };


    /* ==========================================
       INITIAL DASHBOARD LOAD
       ========================================== */

    if (c.userId) {

        c.server.get({

            action: 'loadDashboard',

            userId: c.userId

        }).then(function(response) {

            angular.extend(
                c.data,
                response.data
            );

        });

    }

};

sp_widget.css:
/* ==========================================
   MAIN DASHBOARD
   ========================================== */

.student-dashboard {
    display: flex;
    min-height: 100vh;
    background: #f5f7fa;
    color: #172033;
    font-family: Arial, sans-serif;
}


/* ==========================================
   SIDEBAR
   ========================================== */

.student-sidebar {
    width: 230px;
    min-width: 230px;
    background: #1E293B;
    color: #ffffff;
    min-height: 100vh;
    padding: 22px 14px;
    box-sizing: border-box;
    border-right: 1px solid #334155;
}


.sidebar-brand {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 5px 8px 25px;
    border-bottom: 1px solid rgba(255,255,255,0.12);
}


.brand-icon {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: #2563EB;
    border: 2px solid #60A5FA;
    box-shadow: 0 6px 16px rgba(37,99,235,0.30);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #FFFFFF;
    font-size: 18px;
    font-weight: 700;
}


.sidebar-brand h2 {
    margin: 0;
    font-size: 17px;
    font-weight: 600;
    color: #FFFFFF;
}


.sidebar-brand span {
    display: block;
    margin-top: 3px;
    color: #94A3B8;
    font-size: 11px;
}


.sidebar-menu {
    margin-top: 22px;
}


.sidebar-item {
    width: 100%;
    border: 0;
    background: transparent;
    color: #CBD5E1;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 13px 14px;
    margin-bottom: 7px;
    border-radius: 7px;
    cursor: pointer;
    text-align: left;
    font-size: 14px;
    transition: 0.2s;
}


.sidebar-item:hover {
    background: #334155;
    color: #ffffff;
}


.sidebar-item.active {
    background: #2563EB;
    color: #ffffff;
}


/* ==========================================
   MAIN
   ========================================== */

.student-main {
    flex: 1;
    padding: 30px;
    box-sizing: border-box;
    overflow-x: hidden;
}


.dashboard-section {
    max-width: 1400px;
    margin: 0 auto;
}


.page-header {
    margin-bottom: 25px;
}


.page-header h1 {
    margin: 0;
    font-size: 27px;
    color: #172033;
}


.page-header p {
    margin: 7px 0 0;
    color: #667085;
    font-size: 14px;
}


/* ==========================================
   KPI
   ========================================== */

.kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin-bottom: 25px;
}


.kpi-card {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 10px;
    padding: 22px;
    display: flex;
    align-items: center;
    gap: 15px;
}


.kpi-icon {
    width: 48px;
    height: 48px;
    border-radius: 9px;
    background: #e8f5f3;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 22px;
}


.kpi-content {
    display: flex;
    flex-direction: column;
}


.kpi-label {
    color: #667085;
    font-size: 13px;
    margin-bottom: 5px;
}


.kpi-content strong {
    font-size: 27px;
    color: #172033;
}


/* ==========================================
   CONTENT CARD
   ========================================== */

.content-card {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 10px;
    margin-bottom: 22px;
    overflow: hidden;
}


.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px 22px;
    border-bottom: 1px solid #e5e7eb;
}


.card-header h2 {
    margin: 0;
    font-size: 18px;
}


.card-header p {
    margin: 5px 0 0;
    color: #667085;
    font-size: 13px;
}


/* ==========================================
   TABLE
   ========================================== */

.table-container {
    width: 100%;
    overflow-x: auto;
}


table {
    width: 100%;
    border-collapse: collapse;
    min-width: 700px;
}


th {
    background: #f8fafc;
    color: #475467;
    font-size: 12px;
    font-weight: 600;
    text-align: left;
    padding: 13px 15px;
    border-bottom: 1px solid #e5e7eb;
    white-space: nowrap;
}


td {
    padding: 14px 15px;
    border-bottom: 1px solid #edf0f2;
    font-size: 13px;
    color: #344054;
    vertical-align: middle;
}


tbody tr:hover {
    background: #fafafa;
}


/* ==========================================
   STATUS
   ========================================== */

.status-badge {
    display: inline-block;
    padding: 5px 10px;
    border-radius: 20px;
    background: #eef2f7;
    color: #475467;
    font-size: 11px;
    font-weight: 600;
}


.status-active {
    background: #fff4d6;
    color: #9a6700;
}


.status-resolved {
    background: #dcfce7;
    color: #166534;
}


/* ==========================================
   BUTTONS
   ========================================== */

.primary-button,
.secondary-button {
    border: 0;
    border-radius: 6px;
    padding: 10px 16px;
    font-size: 13px;
    cursor: pointer;
    transition: 0.2s;
}


.primary-button {
    background: #0d9488;
    color: #ffffff;
}


.primary-button:hover {
    background: #0b7f75;
}


.primary-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}


.secondary-button {
    background: #eef2f6;
    color: #344054;
}


.secondary-button:hover {
    background: #e2e7ec;
}


.small-button {
    padding: 7px 11px;
    font-size: 11px;
}


/* ==========================================
   EMPTY STATE
   ========================================== */

.empty-state {
    text-align: center;
    padding: 50px 20px;
}


.empty-icon {
    font-size: 38px;
    margin-bottom: 10px;
}


.empty-state h3 {
    margin: 0 0 7px;
    font-size: 17px;
}


.empty-state p {
    margin: 0 0 18px;
    color: #667085;
    font-size: 13px;
}


/* ==========================================
   FORMS
   ========================================== */

.form-grid,
.feedback-form-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    padding: 24px;
}


.form-group {
    display: flex;
    flex-direction: column;
}


.form-group.full-width {
    grid-column: 1 / -1;
}


.form-group label {
    font-size: 13px;
    font-weight: 600;
    color: #344054;
    margin-bottom: 7px;
}


.required {
    color: #dc2626;
}


.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid #d0d5dd;
    border-radius: 6px;
    padding: 10px 12px;
    font-size: 13px;
    color: #344054;
    background: #ffffff;
    outline: none;
}


.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    border-color: #0d9488;
    box-shadow: 0 0 0 2px rgba(13,148,136,0.08);
}


.form-group textarea {
    resize: vertical;
}


.form-group input[readonly] {
    background: #f8fafc;
    color: #667085;
}


.form-group small {
    margin-top: 6px;
    color: #667085;
    font-size: 11px;
}


.form-actions {
    padding: 0 24px 24px;
    display: flex;
    gap: 10px;
}


.form-error {
    margin: 0 24px 20px;
    padding: 11px 14px;
    background: #fef2f2;
    border: 1px solid #fecaca;
    color: #b91c1c;
    border-radius: 6px;
    font-size: 13px;
}


/* ==========================================
   SUCCESS
   ========================================== */

.success-card {
    display: flex;
    align-items: center;
    gap: 15px;
    background: #ecfdf3;
    border: 1px solid #bbf7d0;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 22px;
}


.success-icon {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: #16a34a;
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
}


.success-card h3 {
    margin: 0 0 4px;
    color: #166534;
    font-size: 16px;
}


.success-card p {
    margin: 0;
    color: #166534;
    font-size: 13px;
}


.success-actions {
    display: flex;
    gap: 10px;
    margin-top: 20px;
}


/* ==========================================
   FEEDBACK
   ========================================== */

.feedback-table {
    min-width: 1500px;
}


.count-badge {
    background: #e8f5f3;
    color: #0d7f75;
    border-radius: 20px;
    padding: 5px 10px;
    font-size: 12px;
    font-weight: 600;
}


/* ==========================================
   RESPONSIVE
   ========================================== */

@media (max-width: 900px) {

    .student-sidebar {
        width: 190px;
        min-width: 190px;
    }

    .student-main {
        padding: 20px;
    }

    .kpi-grid {
        grid-template-columns: 1fr;
    }

}


@media (max-width: 700px) {

    .student-dashboard {
        flex-direction: column;
    }

    .student-sidebar {
        width: 100%;
        min-width: 100%;
        min-height: auto;
    }

    .sidebar-menu {
        display: flex;
        gap: 5px;
        overflow-x: auto;
    }

    .sidebar-item {
        min-width: 150px;
    }

    .form-grid,
    .feedback-form-grid {
        grid-template-columns: 1fr;
    }

    .form-group.full-width {
        grid-column: auto;
    }

}


@media (max-width: 480px) {

    .student-main {
        padding: 15px;
    }

    .page-header h1 {
        font-size: 22px;
    }

    .card-header {
        align-items: flex-start;
        gap: 10px;
        flex-direction: column;
    }

    .form-actions,
    .success-actions {
        flex-direction: column;
    }

    .primary-button,
    .secondary-button {
        width: 100%;
    }

}

sp_widget.script:
(function() {

    /* ==========================================
       INITIAL DATA
       ========================================== */

    data.userId = input && input.userId ? input.userId : '';

    data.userName = '';

    data.kpi = {
        total: 0,
        pending: 0,
        resolved: 0
    };

    data.recentRequests = [];
    data.myRequests = [];

    data.feedbacks = [];
    data.feedbackCount = 0;

    data.messHalls = [];

    data.complaintSuccess = false;
    data.complaintNumber = '';
    data.complaintSysId = '';

    data.feedbackSuccess = false;


    /* ==========================================
       GET USER
       ========================================== */

    if (data.userId) {

        var userGR = new GlideRecord('sys_user');

        if (userGR.get(data.userId)) {

            data.userName = userGR.getDisplayValue('name');

        }

    }


    /* ==========================================
       LOAD MESS HALLS
       ========================================== */

    var messHallGR = new GlideRecord(
        'x_snc_campus_foo_1_mess_hall'
    );

    messHallGR.orderBy('name');
    messHallGR.query();

    while (messHallGR.next()) {

        data.messHalls.push({
            sys_id: messHallGR.getUniqueValue(),
            name: messHallGR.getDisplayValue('name')
        });

    }


    /* ==========================================
       CREATE COMPLAINT
       ========================================== */

    if (
        input &&
        input.action == 'createComplaint'
    ) {

        if (!data.userId) {

            data.complaintSuccess = false;
            data.formError = 'User information is missing.';

        } else {

            var complaintGR = new GlideRecord(
                'x_snc_campus_foo_1_food_complaint'
            );

            complaintGR.initialize();


            /* Student */

            complaintGR.setValue(
                'student',
                data.userId
            );


            /* Complaint fields */

            complaintGR.setValue(
                'use_case',
                input.use_case || ''
            );

            complaintGR.setValue(
                'mess_hall',
                input.mess_hall || ''
            );

            complaintGR.setValue(
                'meal_type',
                input.meal_type || ''
            );

            complaintGR.setValue(
                'problem_type',
                input.problem_type || ''
            );

            complaintGR.setValue(
                'description',
                input.description || ''
            );


            /* Insert */

            var complaintSysId = complaintGR.insert();


            if (complaintSysId) {

                data.complaintSuccess = true;

                data.complaintSysId = complaintSysId;

                data.complaintNumber =
                    complaintGR.getValue('number');

            } else {

                data.complaintSuccess = false;

                data.formError =
                    'Unable to create complaint.';

            }

        }

    }


    /* ==========================================
       LOAD STUDENT COMPLAINTS
       ========================================== */

    if (data.userId) {

        var complaintListGR = new GlideRecord(
            'x_snc_campus_foo_1_food_complaint'
        );


        /* Only logged-in student's complaints */

        complaintListGR.addQuery(
            'student',
            data.userId
        );


        /* Latest first */

        complaintListGR.orderByDesc(
            'sys_created_on'
        );

        complaintListGR.query();


        while (complaintListGR.next()) {

            var stateValue =
                complaintListGR.getValue('state');

            var stateLabel =
                complaintListGR.getDisplayValue('state');


            var request = {

                sys_id:
                    complaintListGR.getUniqueValue(),

                number:
                    complaintListGR.getValue('number'),

                use_case:
                    complaintListGR.getDisplayValue('use_case'),

                mess_hall:
                    complaintListGR.getDisplayValue('mess_hall'),

                meal_type:
                    complaintListGR.getDisplayValue('meal_type'),

                problem_type:
                    complaintListGR.getValue('problem_type'),

                description:
                    complaintListGR.getValue('description'),

                state:
                    stateLabel,

                stateValue:
                    stateValue,

                created:
                    complaintListGR.getDisplayValue(
                        'sys_created_on'
                    )

            };


            data.myRequests.push(request);


            /* ==========================================
               KPI LOGIC

               ACTIVE    = PENDING
               RESOLVED  = RESOLVED

               MONITORING / CLOSED
               ARE NOT COUNTED
               ========================================== */

            data.kpi.total++;


            if (stateValue == 'active') {

                data.kpi.pending++;

            }


            if (stateValue == 'closed') {

                data.kpi.resolved++;

            }

        }


        /* ==========================================
           RECENT 5 REQUESTS
           ========================================== */

        for (
            var i = 0;
            i < data.myRequests.length && i < 5;
            i++
        ) {

            data.recentRequests.push(
                data.myRequests[i]
            );

        }

    }


    /* ==========================================
       SUBMIT FEEDBACK
       ========================================== */

    if (
        input &&
        input.action == 'submitFeedback'
    ) {

        if (!data.userId) {

            data.formError =
                'User information is missing.';

        } else {

            var feedbackUpdateGR =
                new GlideRecord(
                    'x_snc_campus_foo_1_food_complaint_feedbacks'
                );


            if (
                feedbackUpdateGR.get(
                    input.feedbackSysId
                )
            ) {


                /* ==========================================
                   SECURITY CHECK

                   Feedback must belong to current student
                   ========================================== */

                if (
                    feedbackUpdateGR.getValue('student')
                    ==
                    data.userId
                ) {


                    feedbackUpdateGR.setValue(
                        'overall_rating',
                        input.overall_rating
                    );


                    feedbackUpdateGR.setValue(
                        'resolution_satisfaction',
                        input.resolution_satisfaction
                    );


                    feedbackUpdateGR.setValue(
                        'feedback_comments',
                        input.feedback_comments || ''
                    );


                    feedbackUpdateGR.setValue(
                        'feedback_submitted',
                        true
                    );


                    feedbackUpdateGR.update();


                    data.feedbackSuccess = true;

                }

            }

        }

    }


    /* ==========================================
       LOAD PENDING FEEDBACK
       ========================================== */

    if (data.userId) {

        var feedbackGR =
            new GlideRecord(
                'x_snc_campus_foo_1_food_complaint_feedbacks'
            );


        /* Current student */

        feedbackGR.addQuery(
            'student',
            data.userId
        );


        /* Only feedback not yet submitted */

        feedbackGR.addQuery(
            'feedback_submitted',
            false
        );


        feedbackGR.orderByDesc(
            'sys_created_on'
        );

        feedbackGR.query();


        while (feedbackGR.next()) {

            var feedbackSysId =
                feedbackGR.getUniqueValue();


            data.feedbacks.push({

                sys_id:
                    feedbackSysId,

                number:
                    feedbackGR.getValue('number'),

                base_problem:
                    feedbackGR.getDisplayValue(
                        'base_problem'
                    ),

                meal_type:
                    feedbackGR.getDisplayValue(
                        'meal_type'
                    ),

                mess_hall:
                    feedbackGR.getDisplayValue(
                        'mess_hall'
                    ),

                problem_type:
                    feedbackGR.getValue(
                        'problem_type'
                    ),

                use_case:
                    feedbackGR.getDisplayValue(
                        'use_case'
                    ),

                student:
                    feedbackGR.getDisplayValue(
                        'student'
                    ),

                overall_rating:
                    feedbackGR.getValue(
                        'overall_rating'
                    ),

                resolution_satisfaction:
                    feedbackGR.getValue(
                        'resolution_satisfaction'
                    ),

                feedback_comments:
                    feedbackGR.getValue(
                        'feedback_comments'
                    ),

                status:
                    feedbackGR.getDisplayValue(
                        'status'
                    ),

                created:
                    feedbackGR.getDisplayValue(
                        'sys_created_on'
                    )

            });


            data.feedbackCount++;

        }

    }

})();
